  "signal_basis": {
    "component_id": "C007.signal_basis",
    "value": "Reduction testing retains configurations that repeatedly reproduce failure under a common repetition rule, with inconsistent outcomes classified as unresolved. A replay that cannot reproduce the baseline provides no basis for reduction.",
