      ],
      "support_status": "SUFFICIENT",
      "rationale": "The cited spans establish repeated reproduction, consistent outcome assessment, and baseline reproduction as necessary for reduction testing."
    }
  },
  "stated_empirical_relation": {
    "component_id": "C007.stated_empirical_relation",
    "value": "NOT_APPLICABLE",
    "scope": "NOT_APPLICABLE",
    "provenance": {
      "refs": [],
